    start = max(0, target_line - 3)
    end = min(len(lines), target_line + 15)
    print(f"\nShowing lines {start} to {end}\n")
    print("="*80)
    for i in range(start, end):
        try:
            d = json.loads(lines[i])
            t = d.get('type', '?')
            msg = d.get('message', {})
            if isinstance(msg, dict):
                content = msg.get('content', '')
                if isinstance(content, list):
                    text = ' '.join([c.get('text','')[:500] for c in content if isinstance(c, dict) and c.get('type') == 'text'])
