                    text = str(content)[:500]
            else:
                text = str(msg)[:500]
            role = msg.get('role','?') if isinstance(msg, dict) else '?'
            print(f"[{i}] {t}/{role}: {text[:400]}")
            print('-'*80)
        except Exception as e:
            print(f"[{i}] ERR: {e}")
